import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String data = "id,judul,selesai\n1,Belajar,false\n2,Rapat\n";
        CSVFormat format = CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build();
        for (CSVRecord r : CSVParser.parse(data, format)) {
            System.out.println(r.getRecordNumber() + ": konsisten " + r.isConsistent() + ", ada selesai " + r.isSet("selesai"));
        }
    }
}

