import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    static Todo keTodo(CSVRecord r) {
        int id = Integer.parseInt(r.get("id"));
        String judul = r.get("judul").trim();
        boolean selesai = Boolean.parseBoolean(r.get("selesai"));
        return new Todo(id, judul, selesai);
    }

    public static void main(String[] args) throws IOException {
        String data = "id,judul,selesai\n1,Belajar CSV,false\n2,Rapat tim,true\n";
        CSVFormat format = CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build();
        List<Todo> hasil = new ArrayList<>();
        for (CSVRecord r : CSVParser.parse(data, format)) {
            hasil.add(keTodo(r));
        }
        for (Todo t : hasil) {
            System.out.println(t);
        }
    }
}

class Todo {
    private final int id;
    private final String judul;
    private final boolean selesai;

    Todo(int id, String judul, boolean selesai) {
        this.id = id;
        this.judul = judul;
        this.selesai = selesai;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

