import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        CSVFormat format = CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).build();
        List<Produk> masuk = new ArrayList<>();
        for (CSVRecord r : format.parse(new InputStreamReader(System.in))) {
            long baris = r.getRecordNumber() + 1;
            String nama = r.get("nama").trim();
            if (nama.isEmpty()) {
                System.out.println("Baris " + baris + ": nama kosong");
                continue;
            }
            try {
                masuk.add(new Produk(nama, Integer.parseInt(r.get("harga"))));
            } catch (NumberFormatException e) {
                System.out.println("Baris " + baris + ": harga bukan angka");
            }
        }
        System.out.println("Berhasil: " + masuk.size());
    }
}

class Produk {
    final String nama;
    final int harga;

    Produk(String nama, int harga) {
        this.nama = nama;
        this.harga = harga;
    }
}
